(window.webpackJsonp=window.webpackJsonp||[]).push([[109],{456:function(_,v,t){"use strict";t.r(v);var a=t(4),s=Object(a.a)({},(function(){var _=this,v=_._self._c;return v("ContentSlotsDistributor",{attrs:{"slot-key":_.$parent.slotKey}},[v("h1",{attrs:{id:"如何构建知识体系"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#如何构建知识体系"}},[_._v("#")]),_._v(" 如何构建知识体系")]),_._v(" "),v("p",[_._v("前言:")]),_._v(" "),v("p",[_._v("自己每一次从一家公司离职或是离职,即将要找工作就要准备很长时间的面试,只有准备差不多的时候,面试大概率才会过,没准备好,复习时间长心里压力也会很大.于是自己不断反思,为何每一次准备面试都要花很长时间,是否可以将这些时间降低或是减少,直接参与面试,随着反思的深入,我越来越感觉这里面一定有一些别人不知道的秘密,由于看到了一些东西之后,我终于知道这个秘密是什么了.")]),_._v(" "),v("h2",{attrs:{id:"_1-如何解决知识焦虑"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#_1-如何解决知识焦虑"}},[_._v("#")]),_._v(" 1. 如何解决知识焦虑")]),_._v(" "),v("p",[_._v("我们的大脑就像一个容量超大的衣柜，学习知识的过程就像往里头添置衣服的过程。如果你不管什么衣服都往里扔，那么大概率上你每次出门找衣服都要找上半个小时，或者每件只穿两三次就不穿了。但又觉得以后总能穿扔了怪可惜的，所以衣服就越堆越多，但又总觉得自己没衣服穿。这些衣服像不像躺在你收藏家里的那些知识？我们在收藏这些文章之前都有一个共同的想法，那就是这些知识真的好有用，我总有一天能够用上。但事实却是，这些你认为总能用上的链接，自己一次也没有打开过。")]),_._v(" "),v("p",[_._v("有的人觉得见到的所有知识都是自己缺失的，就疯狂的收藏，但这种行为只不过是为了缓解自己内心的焦虑感，而这样并不能够真正的缓解知识焦虑，反而只会加重焦虑，在知识海洋里越来越迷茫。")]),_._v(" "),v("p",[v("strong",[_._v("那么如何解决呢？")]),_._v(" 答案就是建立自己的知识体系。所谓的知识体系指的是将大量的知识点系统有序、指向性明确的组合成某种类型的知识架构，然后通过这个知识架构，我们可以更好的理解某些问题。")]),_._v(" "),v("p",[_._v("知识体系就像蜘蛛网那样，能把不同的知识点有规则的串联起来，从而塑造出我们看到问题、理解问题的思维模式。当我们有了这种思维模式之后，就算把其中一些知识忘掉，我们因此拥有的独立思考能力也可以帮助自己继续工作和生活。而与之相对的则是碎片化的知识点，碎片化的知识就像一根蜘蛛丝，是比较单一的，如果断了就什么也没剩下了。那么如何才能构建自己的知识体系呢？这是一个很大的话题，也是很多粉丝朋友关心的一个问题。")]),_._v(" "),v("h2",{attrs:{id:"_2-如何建立自己的知识体系"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#_2-如何建立自己的知识体系"}},[_._v("#")]),_._v(" 2.如何建立自己的知识体系")]),_._v(" "),v("p",[_._v("今天就给你系统的讲清楚，如何建立自己的知识体系。其实总结下来大概有六个步骤。")]),_._v(" "),v("h3",{attrs:{id:"第一步是-定目标"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#第一步是-定目标"}},[_._v("#")]),_._v(" 第一步是:定目标")]),_._v(" "),v("p",[_._v("首先你得明白一个点，那就是在个人成长领域没有最优、最确定、最权威的知识体系，只有适合我们当前状态的知识体系才是真正的知识体系。获取知识一定是为了解决某一个问题，我们解决问题的构建一定要树立目标。抛开目标谈，构建知识体系是一个伪命题，我们太希望找到一套速成的标准答案了，但你不可能通过构建一套知识体系就去打败工作、生活中的所有问题。所以知识体系的构建一定是目标导向的，先有人生规划，再有清晰的目标。为了实现目标，就需要搭建相应的知识架构，然后再通过这个架构去修炼对应的技能，进军相关专业领域。在这些专业领域里，怎么分门别类的学习，纳入到自己的知识体系中来，怎么获取知识，怎么输出知识等一切问题都围绕着目标，就会非常清晰，避免错误用功.")]),_._v(" "),v("h3",{attrs:{id:"第二步-获取知识。"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#第二步-获取知识。"}},[_._v("#")]),_._v(" 第二步，获取知识。")]),_._v(" "),v("p",[_._v("获取知识是构建知识体系过程中最为重要的一步，因为信息的质量会直接决定了你决策的质量，所以我需要重点讲一讲获取信息的方式，大概可以分为三种，第一是网上冲浪，第二是读书，第三是咨询他人。")]),_._v(" "),v("p",[v("strong",[_._v("第一种:网上冲浪")])]),_._v(" "),v("p",[_._v("但网上冲浪得来的信息大多都趋于碎片化，碎片化的信息为了达到易于习得的目的，通常会显著降低认知成本，最明显的方式就是将复杂的事物简单化。")]),_._v(" "),v("p",[_._v("他们往往只告诉你表面上的东西，却不会告诉你背后的原理以及它与其他事物之间的联系。长期接受碎片化信息的后果就是让你的思维变得狭隘，难以进行复杂的思考。所以如果没有自己的知识体系而去获取大大量的碎片化信息，往往只会造成知识堆砌，从而造成懂很多道理却依然过不好这一生的局面。")]),_._v(" "),v("p",[v("strong",[_._v("第二种是读书，")])]),_._v(" "),v("p",[_._v("读书可以说是我们普通人为数不多能够接触到，也能负担得起的获取高质量信息的渠道。书的知识一般比较系统，思考性强，可以系统的了解某个东西。不管是书籍的系统化结构，还是一本书所承载的思想智慧，都是一条视频或者一篇文章无法比拟的。特别是一些经典书籍，是一些作家终其一生才完成的，而读书其实就是在和这些牛人交流。但很多人读书都会遇到以下几个问题，第一就是没时间。中国人每天的平均休闲时间是2.42个小时，时间都被工作挤压，留给自己的寥寥无几，没时间就成了阻碍阅读的第一元凶。很多人不是不想读书，而是干扰因素太多了。一本书几个礼拜都读不完，即使好不容易读到了结尾，书的开头内容却又忘得差不多了，读了就忘，干脆就不如不读。另外一个问题是，市面上书太多了，根本不知道要读什么。很多朋友不会选书，是因为没有充分评估和了解自己的阅读喜好、知识结构，当下刚需，因此无法有的放矢，找到最适合自己的好书。而有些朋友不知道读什么，则是因为兴趣爱好太广泛，什么都想涉猎，结果根本不知从何下手。相信这些都是让很多朋友颇感头疼的问题。")]),_._v(" "),v("p",[v("strong",[_._v("第三种方式是咨询他人")])]),_._v(" "),v("p",[_._v("付费购买信息，一直都是获取优质信息的快捷方式，但对于大多数人而言，先构建底层知识体系，在购买信息、拓展知识体系，才能达到锦上添花的效果。否则，很容易因为认知不同品，使你无法理解该信息的核心要义，最终不仅仅浪费了钱财，还浪费了精力。")]),_._v(" "),v("h3",{attrs:{id:"第三步-提炼知识"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#第三步-提炼知识"}},[_._v("#")]),_._v(" 第三步，提炼知识，")]),_._v(" "),v("p",[_._v("剔除无用沉余的知识，并且将知识模块化.")]),_._v(" "),v("p",[_._v("整理知识和整理物品一样，我们的大脑就是一个每天通过手机、电脑交谈、分享、接收各种信息和知识的房间，如果房间内的知识不及时删除、整理、排除、扔掉一些东西，长时间大脑就会一团糟。即使是你学过的知识，遇到问题时你也会记不起来。很多时候，我们每天刷视频、看朋友圈，接受了那么多的信息，很多是无用的。")]),_._v(" "),v("p",[_._v("高效人士会有意的屏蔽一些信息，而且一般牛人大脑过滤、筛选信息的能力要比其他人强。一场演讲嘉宾演讲了2个小时，真正有用的就几点。")]),_._v(" "),v("p",[_._v("所以需要对知识进行删减和提炼，筛选提炼的目的有两个，一是为了找到重点，二是便于记忆，你只有记住了重点，下次遇见同样的问题时才能帮助到你。")]),_._v(" "),v("p",[_._v("然后要对知识进行模块化。知识模块化的主要目的在于方便调用。就像衣柜里的衣服一样，你将每一种样式都分门别类的放好，要用的时候直接取用就可以。知识也是如此，将知识模块化最好的方式是用思维导图把这些底层理论和方法论整理出来，形成一个又一个的知识模块。这样，面对类似现象层面的问题时，就完全可以把对应知识模块搬出来解决，面对复杂问题时就用多个知识模块。")]),_._v(" "),v("h3",{attrs:{id:"第四步-关联重构。"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#第四步-关联重构。"}},[_._v("#")]),_._v(" 第四步，关联重构。")]),_._v(" "),v("p",[_._v("知识不是简单的堆积，而在于制造关联，不然无法构成体系。")]),_._v(" "),v("p",[_._v("要克服知识碎片化带来的零散、不系统的弊病，必须构建知识点之间的联系。如果把知识体系当做一棵树，知识点是这棵树上的叶，知识是有层级和关系的，它们由树根、树干、树枝所代表的关系，根本可以探索到树枝所代表的知识细节，树叶所在的树枝又可以追溯到树根所代表的主旨信息。每一棵树枝又包含着相应层级的知识，每一条枝干又代表着相互的关系，它们组合在一起，构成了特定范围内的知识体系。")]),_._v(" "),v("h3",{attrs:{id:"第五步-输出。"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#第五步-输出。"}},[_._v("#")]),_._v(" 第五步，输出。")]),_._v(" "),v("p",[_._v("输出的过程是实践的过程，是把别人的知识变成自己的知识的过程，是知识从理论到实践的过程。我们不可能从思维养成一种实践习惯，而只能从不断实践中养成一种思维模式。知识也一样，必须要输出才行，也就是分享、交流和实践，不然就是死。知识是没有任何用处的，比如记笔记、写文章、做产品等等，这都是输出，有助于强化原来的知识模块，而且在输出的过程中会有很多人来提问或者交流，这同时也是对原有知识模块的一种重新思考和检验。")]),_._v(" "),v("h3",{attrs:{id:"第六步-聚合。"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#第六步-聚合。"}},[_._v("#")]),_._v(" 第六步，聚合。")]),_._v(" "),v("p",[_._v("想要完整的构建一套知识体系，一定要经历知识的分解和再聚合。知识的分解和再聚合是从理论到实践再到理论的循环迭代过程。")]),_._v(" "),v("p",[_._v("同一领域的知识模块归类组合到一起，会形成一套知识体系，而要将多个知识体系最终融会贯通起来，也必须通过大量的实践。这是因为知识体系的建立由实践和问题驱动，问题和实践能够分解离散原来知识模块中的点，这些点在解决问题的实践中不断的进行重构，然后再通过总结和归纳来思考如何从底向上抽象形成某一个领域的完整知识体系。")]),_._v(" "),v("h3",{attrs:{id:"小结"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#小结"}},[_._v("#")]),_._v(" 小结")]),_._v(" "),v("p",[_._v("这就是建立知识体系的六大步骤。一个项目如果我们没梳理出运作项目的知识体系，那么只能凭经验做，遇到经验之外的事也就很难应对。而梳理出一套运作项目的知识体系之后，你就能从全局掌握如何运作项目，继而可以有结构有顺序的开展工作，并能轻松应对各类新事物。当深入一个领域时，拥有知识体系，你能够从全局掌握该领域的概貌，而且也清楚自己在该领域各部分与他人的差距，进而找到自己深入该领域的目标及路径，这便是建立知识体系的强大之处。")]),_._v(" "),v("h2",{attrs:{id:"_1-如何应用"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#_1-如何应用"}},[_._v("#")]),_._v(" 1.如何应用")]),_._v(" "),v("h3",{attrs:{id:"_1-3-如何才能将题做透"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#_1-3-如何才能将题做透"}},[_._v("#")]),_._v(" 1.3 如何才能将题做透")]),_._v(" "),v("ul",[v("li",[v("p",[_._v("第一种:做的这个题背后的知识点能讲出来,能背过,张嘴就能说,给大家说明白基础知识")])]),_._v(" "),v("li",[v("p",[_._v("第二种:能够书写完整解题过程 ,这个题目因为什么,所以什么,根据什么,所以什么,这一阶段主要梳理逻辑思路")])]),_._v(" "),v("li",[v("p",[_._v("第三种:费曼学习法,给别人讲,给自己讲.用生活中的语言来说明")])]),_._v(" "),v("li",[v("p",[_._v("第四种:要学会把题目模型化,这一道题就要发挥一类题的作用.这一类题都是遵循什么样的原理,利用什么样的知识点,使用了一个什么样的技巧, 解题的过程中,我们的思路是什么,解答的套路是什么,把一道题做成一类题,一道题发挥10道题的作用,有总结有输出哪就是你沉淀下来的结论经验技巧")])])]),_._v(" "),v("h3",{attrs:{id:"_1-4记忆的诀窍"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#_1-4记忆的诀窍"}},[_._v("#")]),_._v(" 1.4记忆的诀窍")]),_._v(" "),v("p",[v("strong",[_._v("第一招:冥想回忆法:")])]),_._v(" "),v("p",[_._v("读完一遍知识点内容后,在白纸上梳理一遍整个知识点的框架,然后在脑海中梳理一遍,接着再去复习记忆,你会发现很多不同的地方,仿佛瞬间被打通了背书的任督二脉")]),_._v(" "),v("p",[v("strong",[_._v("第二招:框架加关键词法")])]),_._v(" "),v("ul",[v("li",[v("p",[_._v("第一步:复习时拿一张白纸,在纸上默写框架和关键词,将这一章节全部默写一遍,默写不出来的话,就想像你现在在考试,给他硬编一个答案,也得把这一章过了")])]),_._v(" "),v("li",[v("p",[_._v("第二步背完一章,去翻书,把你和书上不一样的地方用红笔勾出来,会发现书上的句子真的老高级了,会有一种恍然大悟的")])]),_._v(" "),v("li",[v("p",[_._v("第三步就是把红色的部分就是没编出来的再背一遍,等下次你再默写,你就会发现那种恍然大悟的高级句子了,你印像特别深刻,不自觉的就记住了.")])])]),_._v(" "),v("p",[v("strong",[_._v("第三招:番茄工作法,干25分钟,休息5分钟")])]),_._v(" "),v("h3",{attrs:{id:"_1-5-时间点复习法"}},[v("a",{staticClass:"header-anchor",attrs:{href:"#_1-5-时间点复习法"}},[_._v("#")]),_._v(" 1.5 时间点复习法")]),_._v(" "),v("p",[_._v("第一时间点在早上:")]),_._v(" "),v("p",[_._v("当前新内容背诵结束完成之后,要进行一次回忆,在整个回忆过程当中,是不允许翻书的,准备一张白张或是ipad,然后默写出刚刚背诵的这一章的框架结构,先写出框架结构,再细化出具体内容 ,对于大段内容的阐述,我们可以只采用关键词,对于想不起的地方也不要翻书,做上标记之后,继续往下回忆直到这一章完全结束,然后我们再翻开书本,着重去记忆这些薄弱的知识点,边写边背是为了帮助你集中注意力,防止你在这个过程中分心,以及他也能真正帮助你检测出,你到底能够记住多少,所以你在写的时候,根本不需要写的多规整")]),_._v(" "),v("p",[_._v("第二个时间点在临睡前 ,")]),_._v(" "),v("p",[_._v("将早上背过的内容,再回忆一遍和早上的规矩是一样的,全程不允许翻书")]),_._v(" "),v("p",[_._v("第三个时间点,在开始学习新知识之前,要把昨天的旧知识,再回忆一下 ,这个时候你会发现,你能记住90%的内容")])])}),[],!1,null,null,null);v.default=s.exports}}]);